public class Person {
    public string Name { get; set; }
}

public class Student : Person { }

public class C {
    public string M(Person p) {
        return p switch  {
            { Name: "Bill" } => "Hey Bill!",
            Student { Name: var name } => "Hello student { name}!",
            _ => null,
        };
    }
}
